package com.pp.shaderlod.optimization.sildurspatial;
import java.util.*;import org.lwjgl.opengl.*;import net.irisshaders.iris.targets.RenderTargets;import com.pp.shaderlod.optimization.blissspatial.BlissSpatialGl;import com.pp.shaderlod.optimization.photon.PhotonSpatialEpoch;import com.pp.shaderlod.optimization.makeupao.MakeUpAoGlProof;
/** Sildur native deferred material/lightmap/normal/shadow sampler basis, current binding proof. */
public final class SildurSpatialGl {
 public record Proof(PhotonSpatialEpoch.Output output,Map<String,BlissSpatialGl.Sample> inputs,boolean valid,String reason){}
 private static String refusal="none",snapshot="not queried";
 private static void refuse(String why){if(refusal.equals("none"))refusal=why;}
 private static boolean rejected(String why){refuse(why);return false;}
 private static String target(RenderTargets t,int index){var x=t.get(index);return x==null?"absent":x.getMainTexture()+"/"+x.getAltTexture()+" "+x.getWidth()+"x"+x.getHeight()+" "+x.getInternalFormat();}
 private SildurSpatialGl(){}
 public static int integer(int p,String n){return MakeUpAoGlProof.integer(p,n);}
 public static boolean owned(RenderTargets t,int index,int texture){var r=t.get(index);return r!=null&&texture>0&&(r.getMainTexture()==texture||r.getAltTexture()==texture)&&r.getWidth()==t.getCurrentWidth()&&r.getHeight()==t.getCurrentHeight();}
 private static int output(int slot){int a=GL11.glGetInteger(GL20.GL_DRAW_BUFFER0+slot);return a==GL30.GL_COLOR_ATTACHMENT0+slot&&GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,a,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE)==GL11.GL_TEXTURE&&GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,a,GL30.GL_FRAMEBUFFER_ATTACHMENT_TEXTURE_LEVEL)==0?GL30.glGetFramebufferAttachmentParameteri(GL30.GL_DRAW_FRAMEBUFFER,a,GL30.GL_FRAMEBUFFER_ATTACHMENT_OBJECT_NAME):0;}
 public static String nativeInputsStatus(){return "first="+refusal+" inputs="+snapshot;}
 public static Map<String,BlissSpatialGl.Sample> inputs(RenderTargets t,int p){refusal="none";snapshot="not queried";var m=new TreeMap<String,BlissSpatialGl.Sample>();var observed=new TreeMap<String,String>();boolean valid=true;
 for(String name:List.of("colortex1","colortex2","colortex4","depthtex0","depthtex2","noisetex","shadowtex0","shadowtex1","shadowcolor0")){
  String actual=name.startsWith("shadowtex")?name+"HW":name;int unit=integer(p,actual);if(unit<0){observed.put(name,"inactive");continue;}var sample=BlissSpatialGl.sample(p,actual);observed.put(name,"uniform="+actual+" unit="+unit+" "+sample);
  if(!BlissSpatialGl.lodParity(sample)){refuse("sampler "+name+" LOD0/native parity");valid=false;continue;}if(sample.image().compare()!=(name.startsWith("shadowtex")?GL30.GL_COMPARE_REF_TO_TEXTURE:GL11.GL_NONE)){refuse("sampler "+name+" comparison mode");valid=false;continue;}m.put(name,sample);
 }
 snapshot=observed.toString();
 for(String key:List.of("colortex1","colortex2","depthtex0","depthtex2","shadowtex0"))if(!m.containsKey(key)){refuse("required sampler "+key+" absent/invalid");valid=false;}
 if(!valid)return null;
 for(int index:new int[]{1,2})if(!owned(t,index,m.get("colortex"+index).image().texture())){refuse("owned native target"+index+" differs expected="+target(t,index));valid=false;}
 if(m.get("depthtex0").image().texture()!=t.getDepthTexture()){refuse("native depth0 differs expected="+t.getDepthTexture());valid=false;}
 if(m.get("depthtex2").image().texture()!=t.getDepthTextureNoHand().getTextureId()){refuse("native depth2 differs expected="+t.getDepthTextureNoHand().getTextureId());valid=false;}
 return valid?Map.copyOf(m):null;}
 private static boolean state(RenderTargets t,int p,boolean half,int slots){int[] v=new int[4];GL11.glGetIntegerv(GL11.GL_VIEWPORT,v);if(!Arrays.equals(v,new int[]{0,0,half?t.getCurrentWidth()/2:t.getCurrentWidth(),half?t.getCurrentHeight()/2:t.getCurrentHeight()})||t.getCurrentWidth()<4||t.getCurrentHeight()<4||t.getCurrentWidth()>8192||t.getCurrentHeight()>8192)return rejected("viewport="+Arrays.toString(v)+" native="+t.getCurrentWidth()+"x"+t.getCurrentHeight()+" half="+half);
 for(int i=0;i<slots;i++){var mask=org.lwjgl.BufferUtils.createByteBuffer(4);GL30.glGetBooleani_v(GL11.GL_COLOR_WRITEMASK,i,mask);for(int c=0;c<4;c++)if(mask.get(c)==0)return rejected("write mask slot="+i+" component="+c);if(GL30.glIsEnabledi(GL11.GL_BLEND,i))return rejected("blend enabled slot="+i);}
 var caps=GL.getCapabilities();boolean unclamped=caps.OpenGL33&&((GL11.glGetInteger(GL32.GL_CONTEXT_PROFILE_MASK)&GL32.GL_CONTEXT_CORE_PROFILE_BIT)!=0||GL11.glGetInteger(GL30.GL_CLAMP_FRAGMENT_COLOR)!=GL11.GL_TRUE);
 boolean qualified=unclamped&&GL11.glGetInteger(GL20.GL_CURRENT_PROGRAM)==p&&GL20.glGetProgrami(p,GL20.GL_LINK_STATUS)==GL11.GL_TRUE&&GL30.glCheckFramebufferStatus(GL30.GL_DRAW_FRAMEBUFFER)==GL30.GL_FRAMEBUFFER_COMPLETE&&!GL11.glIsEnabled(GL11.GL_DEPTH_TEST)&&!GL11.glIsEnabled(GL11.GL_STENCIL_TEST)&&com.pp.shaderlod.optimization.blissspatial.BlissSpatialCull.allowed(GL11.glIsEnabled(GL11.GL_CULL_FACE),GL11.glGetInteger(GL11.GL_CULL_FACE_MODE),GL11.glGetInteger(GL11.GL_FRONT_FACE),com.pp.shaderlod.optimization.blissspatial.BlissSpatialCull.exact())&&!GL11.glIsEnabled(GL11.GL_SCISSOR_TEST)&&!GL11.glIsEnabled(GL30.GL_RASTERIZER_DISCARD)&&!GL11.glIsEnabled(GL11.GL_COLOR_LOGIC_OP)&&integer(p,"shaderlodBridgeVersion")==2&&integer(p,"shaderlodEnabled")==1&&integer(p,"shaderlodOptimizationFlagsVersion")==1&&Set.of(0,1,2).contains(integer(p,"shaderlodPreset"));if(!qualified){var states=new TreeMap<Integer,Boolean>();for(int flag:new int[]{GL11.GL_DEPTH_TEST,GL11.GL_STENCIL_TEST,GL11.GL_CULL_FACE,GL11.GL_SCISSOR_TEST,GL30.GL_RASTERIZER_DISCARD,GL11.GL_COLOR_LOGIC_OP})states.put(flag,GL11.glIsEnabled(flag));refuse("state/protocol unclamped="+unclamped+" current="+GL11.glGetInteger(GL20.GL_CURRENT_PROGRAM)+" expected="+p+" linked="+GL20.glGetProgrami(p,GL20.GL_LINK_STATUS)+" fbo="+GL11.glGetInteger(GL30.GL_DRAW_FRAMEBUFFER_BINDING)+" status="+GL30.glCheckFramebufferStatus(GL30.GL_DRAW_FRAMEBUFFER)+" states="+states+" cull="+GL11.glGetInteger(GL11.GL_CULL_FACE_MODE)+" front="+GL11.glGetInteger(GL11.GL_FRONT_FACE)+" bridge="+integer(p,"shaderlodBridgeVersion")+" enabled="+integer(p,"shaderlodEnabled")+" flags="+integer(p,"shaderlodOptimizationFlagsVersion")+" preset="+integer(p,"shaderlodPreset")+" cullCertificate="+com.pp.shaderlod.optimization.blissspatial.BlissSpatialCull.status());}return qualified;}
 public static Proof producer(RenderTargets t,int p,boolean half){refusal="none";snapshot="not queried";int field=output(0);var inputs=inputs(t,p);var rt=t.get(12);boolean valid=state(t,p,half,1)&&owned(t,12,field)&&rt!=null&&rt.getInternalFormat().name().equals("RGBA32F")&&inputs!=null&&inputs.values().stream().noneMatch(s->s.image().texture()==field);return new Proof(new PhotonSpatialEpoch.Output(field,field,GL11.glGetInteger(GL30.GL_DRAW_FRAMEBUFFER_BINDING)),inputs,valid,valid?"qualified":(refusal.equals("none")?"attachment/format/alias native12="+target(t,12)+" native4="+target(t,4)+" native6="+target(t,6):refusal)+" inputs="+snapshot);}
 public static Proof consumer(RenderTargets t,int p){refusal="none";snapshot="not queried";var field=BlissSpatialGl.sample(p,"colortex12");var inputs=inputs(t,p);int out=output(0);boolean valid=state(t,p,false,2)&&field!=null&&field.image().format()==GL30.GL_RGBA32F&&field.image().base()==0&&field.image().compare()==GL11.GL_NONE&&field.image().min()==GL11.GL_NEAREST&&field.image().mag()==GL11.GL_NEAREST&&field.image().aniso()==1&&field.swizzle().equals(List.of(GL11.GL_RED,GL11.GL_GREEN,GL11.GL_BLUE,GL11.GL_ALPHA))&&owned(t,12,field.image().texture())&&inputs!=null&&owned(t,4,out)&&owned(t,6,output(1))&&inputs.containsKey("colortex4")&&owned(t,4,inputs.get("colortex4").image().texture())&&inputs.values().stream().noneMatch(s->s.image().texture()==out||s.image().texture()==output(1))&&out!=inputs.get("colortex4").image().texture()&&out!=field.image().texture();return new Proof(new PhotonSpatialEpoch.Output(field==null?0:field.image().texture(),field==null?0:field.image().texture(),GL11.glGetInteger(GL30.GL_DRAW_FRAMEBUFFER_BINDING)),inputs,valid,valid?"qualified":(refusal.equals("none")?"attachment/format/alias field="+field+" outputs="+out+"/"+output(1)+" native12="+target(t,12)+" native4="+target(t,4)+" native6="+target(t,6):refusal)+" inputs="+snapshot);}
 public static Map<String,Integer> controls(int program){var result=new TreeMap<>(com.pp.shaderlod.optimization.photon.PhotonSpatialGl.controls(program));
  result.put("shaderlodSildurReceiverPermission",integer(program,"shaderlodSildurReceiverPermission"));for(var id:com.pp.shaderlod.optimization.OptimizationId.values()){int l=GL20.glGetUniformLocation(program,id.uniform());if(l>=0)result.put(id.uniform(),GL20.glGetUniformi(program,l));}
  for(String name:List.of("viewWidth","viewHeight","rainStrength","nightVision","frameTimeCounter","far","aspectRatio","sunPosition","upPosition","shadowLightPosition","shadowModelView","shadowProjection","gbufferProjection","gbufferProjectionInverse","gbufferModelViewInverse")){
   int l=GL20.glGetUniformLocation(program,name);if(l<0)continue;int count=name.contains("Projection")||name.contains("ModelView")?16:name.endsWith("Position")?3:1;float[] v=new float[count];GL20.glGetUniformfv(program,l,v);for(int j=0;j<count;j++)result.put(name+"["+j+"]",Float.floatToRawIntBits(v[j]));
  }
  for(String name:List.of("isEyeInWater","isNether","heldBlockLightValue","heldBlockLightValue2","worldTime","framemod8","frameCounter","eyeBrightnessSmooth")){
   int l=GL20.glGetUniformLocation(program,name);if(l<0)continue;int count=name.equals("eyeBrightnessSmooth")?2:1;int[] v=new int[count];GL20.glGetUniformiv(program,l,v);for(int j=0;j<count;j++)result.put(name+"["+j+"]",v[j]);
  }return Map.copyOf(result);
 }
 public static boolean sameControls(Map<String,Integer> produced,Map<String,Integer> consumed){return produced!=null&&consumed!=null&&consumed.entrySet().containsAll(produced.entrySet());}
 public static void upload(int p,boolean ready,int width,int height){int l=GL20.glGetUniformLocation(p,"shaderlodSildurSpatialReady");if(l>=0)GL20.glUniform1i(l,ready?1:0);l=GL20.glGetUniformLocation(p,"shaderlodSildurSpatialSize");if(l>=0)GL20.glUniform2f(l,width,height);}
}
